 "content": "def transform(grid):
    g = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) != 2:
        return g
    (r1, c1), (r2, c2) = markers
    # Reflect the colored motif through the midpoint between the marker points.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v not in (0, 5):
                rr, cc = r1 + r2 - r, c1 + c2 - c
                if 0 <= rr < len(g) and 0 <= cc < len(g[0]):
                    g[rr][cc] = v
    g[r2][c2] = 0
    return g
